let cacheErrors = 0;
const brokenCache = {
  get: async (_key: string): Promise<string | undefined> => {
    throw new Error("ECONNREFUSED");
  },
};
const database = { find: async (id: number) => `product ${id} from the database` };

async function getProduct(id: number): Promise<string> {
  try {
    const hit = await brokenCache.get(`product:${id}`);
    if (hit !== undefined) return hit;
  } catch {
    cacheErrors += 1;
  }
  return database.find(id);
}

console.log(await getProduct(1));
console.log("cache errors:", cacheErrors);

