function hitRate(stats: { hits: number; misses: number }): string {
  const total = stats.hits + stats.misses;
  return total === 0 ? "n/a" : `${((stats.hits / total) * 100).toFixed(1)}%`;
}

console.log(hitRate({ hits: 297, misses: 3 }), hitRate({ hits: 1, misses: 2 }), hitRate({ hits: 0, misses: 0 }));
